"use client";

import { useEffect, useState } from "react";
import api from "@/lib/api";
import { useSocket } from "@/contexts/SocketContext";
import { useAuth } from "@/contexts/AuthContext";
import { Phone, Video } from "lucide-react";

export default function CallPage() {
  const { user } = useAuth();
  const { socket, onlineUsers } = useSocket() || {}; // prevent null error

  const [users, setUsers] = useState([]);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const res = await api.get("/users");
        setUsers(res.data);
      } catch (err) {
        console.error(
          "❌ Failed to fetch users:",
          err?.response?.data || err.message
        );
      }
    };

    fetchUsers();
  }, []);

  const handleCall = (targetId, isVideo = false) => {
    if (!socket || !user) return;
    if (!onlineUsers.includes(targetId)) {
      alert("User is not online.");
      return;
    }

    socket.emit("call_user", {
      to: targetId,
      from: user.id,
      isVideo,
    });

    alert(`📞 Calling ${targetId} (${isVideo ? "video" : "voice"})...`);
  };

  return (
    <div className="p-6 max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">📞 Call Users</h1>
      <ul className="space-y-4">
        {users
          .filter((u) => u.id !== user?.id)
          .map((u) => (
            <li
              key={u.id}
              className="flex items-center justify-between border p-4 rounded-lg shadow"
            >
              <div className="flex items-center space-x-2">
                <span className="font-medium">{u.username}</span>
                <span
                  className={`text-sm ${
                    onlineUsers?.includes(u.id)
                      ? "text-green-500"
                      : "text-gray-400"
                  }`}
                >
                  {onlineUsers?.includes(u.id) ? "🟢 Online" : "🔴 Offline"}
                </span>
              </div>
              <div className="flex space-x-2">
                <button
                  onClick={() => handleCall(u.id, false)}
                  className="bg-blue-500 hover:bg-blue-600 text-white px-3 py-1 rounded"
                >
                  <Phone size={18} />
                </button>
                <button
                  onClick={() => handleCall(u.id, true)}
                  className="bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded"
                >
                  <Video size={18} />
                </button>
              </div>
            </li>
          ))}
      </ul>
    </div>
  );
}
